WITH DATA_FILTRO_CTE AS (    SELECT         CASE            WHEN :VAR_MES_FILTRO IS NULL OR :VAR_MES_FILTRO = 'Todos'             THEN LAST_DAY(STR_TO_DATE(CONCAT('31/12/', :VAR_ANO_FILTRO), '%d/%m/%Y'))            ELSE LAST_DAY(STR_TO_DATE(CONCAT('01/', :VAR_MES_FILTRO), '%d/%m/%Y'))        END AS DATA_FILTRO,         CASE            WHEN :VAR_MES_FILTRO IS NULL OR :VAR_MES_FILTRO = 'Todos'             THEN LAST_DAY(STR_TO_DATE(CONCAT('31/12/', :VAR_ANO_FILTRO - 1), '%d/%m/%Y'))            ELSE LAST_DAY(DATE_SUB(STR_TO_DATE(CONCAT('01/', :VAR_MES_FILTRO), '%d/%m/%Y'), INTERVAL 1 YEAR))        END AS DATA_FILTRO_ANT),base_bal AS (    SELECT        CTACTB,        SUM(CASE WHEN REFERENCIA <= (SELECT DATA_FILTRO FROM DATA_FILTRO_CTE) THEN VLRLANC ELSE 0 END) AS total_atu,        SUM(CASE WHEN YEAR(REFERENCIA) = :VAR_ANO_FILTRO AND REFERENCIA <= (SELECT DATA_FILTRO FROM DATA_FILTRO_CTE) THEN VLRLANC ELSE 0 END) AS ytd_atu,        SUM(CASE WHEN REFERENCIA <= (SELECT DATA_FILTRO_ANT FROM DATA_FILTRO_CTE) THEN VLRLANC ELSE 0 END) AS total_ant,        SUM(CASE WHEN YEAR(REFERENCIA) = (:VAR_ANO_FILTRO - 1) AND REFERENCIA <= (SELECT DATA_FILTRO_ANT FROM DATA_FILTRO_CTE) THEN VLRLANC ELSE 0 END) AS ytd_ant,        SUM(CASE WHEN REFERENCIA < MAKEDATE(:VAR_ANO_FILTRO, 1) THEN VLRLANC ELSE 0 END) AS saldo_final_ano_anterior,        SUM(CASE WHEN REFERENCIA < MAKEDATE(:VAR_ANO_FILTRO - 1, 1) THEN VLRLANC ELSE 0 END) AS saldo_final_ano_retrasado    FROM IMP_BASE_BALANCETE    WHERE CODEMP = :VAR_EMPRESA_DRE    GROUP BY CTACTB),regras_contas AS (    SELECT DISTINCT        DET.ORDEM, DET.NOME_GRUPO, DET.COD_NOTA_EXPLICATIVA, C.PADRAO_CTACTB, C.SINAL    FROM ESTR_DEMONSTRATIVOS EST    JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO    JOIN DET_DEMONSTRATIVO_ANO DA ON DET.ID = DA.ID_DET_DEMONSTRATIVO    JOIN DET_DEMONSTRATIVO_REFERENCIA R ON DA.ID = R.ID_DET_DEMONSTRATIVO_ANO    JOIN DET_DEMONSTRATIVO_CTACTB C ON R.ID = C.ID_DET_DEMONSTRATIVO_REFERENCIA    WHERE EST.ID = 1 AND DA.ANO = :VAR_ANO_FILTRO AND R.REFERENCIA = (SELECT MAX(R2.REFERENCIA) FROM DET_DEMONSTRATIVO_REFERENCIA R2 WHERE R2.ID_DET_DEMONSTRATIVO_ANO = DA.ID AND R2.REFERENCIA <= (SELECT DATA_FILTRO FROM DATA_FILTRO_CTE))),regras_excluidas AS (    SELECT DISTINCT DET.ORDEM, C.PADRAO_CTACTB    FROM ESTR_DEMONSTRATIVOS EST    JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO    JOIN DET_DEMONSTRATIVO_ANO DA ON DET.ID = DA.ID_DET_DEMONSTRATIVO    JOIN DET_DEMONSTRATIVO_REFERENCIA R ON DA.ID = R.ID_DET_DEMONSTRATIVO_ANO    JOIN DET_DEMONSTRATIVO_CTACTB_EXC C ON R.ID = C.ID_DET_DEMONSTRATIVO_REFERENCIA    WHERE EST.ID = 1 AND DA.ANO = :VAR_ANO_FILTRO AND R.REFERENCIA = (SELECT MAX(R2.REFERENCIA) FROM DET_DEMONSTRATIVO_REFERENCIA R2 WHERE R2.ID_DET_DEMONSTRATIVO_ANO = DA.ID AND R2.REFERENCIA <= (SELECT DATA_FILTRO FROM DATA_FILTRO_CTE))),contas_mapeadas AS (    SELECT        R.ORDEM, R.NOME_GRUPO, R.COD_NOTA_EXPLICATIVA, R.SINAL,        CASE            WHEN TRIM(R.ORDEM) = '3.3.1' THEN B.saldo_final_ano_anterior            WHEN TRIM(R.ORDEM) = '3.3.2' THEN B.ytd_atu            ELSE B.total_atu        END AS valor_atu,        CASE            WHEN TRIM(R.ORDEM) = '3.3.1' THEN B.saldo_final_ano_retrasado            WHEN TRIM(R.ORDEM) = '3.3.2' THEN B.ytd_ant            ELSE B.total_ant        END AS valor_ant,        ROW_NUMBER() OVER(PARTITION BY B.CTACTB, R.ORDEM ORDER BY LENGTH(R.PADRAO_CTACTB) DESC) as rn    FROM base_bal B    JOIN regras_contas R ON B.CTACTB LIKE R.PADRAO_CTACTB    LEFT JOIN regras_excluidas E ON R.ORDEM = E.ORDEM AND B.CTACTB LIKE E.PADRAO_CTACTB    WHERE E.PADRAO_CTACTB IS NULL)SELECT    R.ORDEM, R.NOME_GRUPO, R.COD_NOTA_EXPLICATIVA,    SUM(IFNULL(M.valor_atu, 0) * M.SINAL) AS VLRLANC_ATU,    SUM(IFNULL(M.valor_ant, 0) * M.SINAL) AS VLRLANC_ANTFROM (SELECT DISTINCT ORDEM, NOME_GRUPO, COD_NOTA_EXPLICATIVA FROM regras_contas) RLEFT JOIN contas_mapeadas M ON R.ORDEM = M.ORDEM AND R.NOME_GRUPO = M.NOME_GRUPO AND M.rn = 1GROUP BY R.ORDEM, R.NOME_GRUPO, R.COD_NOTA_EXPLICATIVAORDER BY R.ORDEMLIMIT 500